122:       BOOL ret = QueryPerformanceCounter((LARGE_INTEGER *)&x);
123:       //SetThreadAffinityMask(hCurThread, dwOldMask);
124:       if (!ret)
125:          x = getTime() * s_ullCPUFrequency;
126:    #elif defined(OSX)
127:       x = mach_absolute_time();
