693: {
694:    if (AF_INET == ver)
695:    {
696:       sockaddr_in* a1 = (sockaddr_in*)addr1;
697:       sockaddr_in* a2 = (sockaddr_in*)addr2;
698: 
699:       if ((a1->sin_port == a2->sin_port) && (a1->sin_addr.s_addr == a2->sin_addr.s_addr))
