306: int CSndUList::pop(sockaddr*& addr, CPacket& pkt)
307: {
308:    CGuard listguard(m_ListLock);
309: 
310:    if (-1 == m_iLastEntry)
311:       return -1;
312: 
313:    // no pop until the next schedulled time
314:    uint64_t ts;
315:    CTimer::rdtsc(ts);
316:    if (ts < m_pHeap[0]->m_llTimeStamp)
317:       return -1;
318: 
319:    CUDT* u = m_pHeap[0]->m_pUDT;
320:    remove_(u);
321: 
322:    if (!u->m_bConnected || u->m_bBroken)
323:       return -1;
324: 
325:    // pack a packet from the socket
326:    if (u->packData(pkt, ts) <= 0)
327:       return -1;
328: 
329:    addr = u->m_pPeerAddr;
330: 
331:    // insert a new entry, ts is the next processing time
332:    if (ts > 0)
333:       insert_(ts, u);
334: 
335:    return 1;
