359:    // do not insert repeated node
360:    if (n->m_iHeapLoc >= 0)
361:       return;
362: 
363:    m_iLastEntry ++;
364:    m_pHeap[m_iLastEntry] = n;
365:    n->m_llTimeStamp = ts;
366: 
367:    int q = m_iLastEntry;
368:    int p = q;
369:    while (p != 0)
